دالة حاصل_الجمع_المزدوج(ق، هدف) {
    من_أجل (أ من ٠ إلى طول(ق) - ١) {
        من_أجل (ب من أ + ١ إلى طول(ق) - ١) {
            إذا (ق[أ] + ق[ب] == هدف) {
                ارجع صحيح
            }
        }
    }
    ارجع خطأ
}
```

